AssistantMessageToolRequest(name='create', tool_call_id='tooluse_Jy20qztjCNfpxAX9R90xsL', arguments={'file_text': '/* ── Reset & tokens ───────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-bg:          #f8f7f5;
  --clr-surface:     #ffffff;
  --clr-surface-2:   #f1efec;
  --clr-border:      #e2deda;
  --clr-text:        #1a1a1a;
  --clr-text-muted:  #6b6560;
  --clr-accent:      #c0392b;
  --clr-accent-hover:#a93226;
  --clr-accent-lt:   #fdf0ef;
  --clr-deal:        #e67e22;
  --clr-deal-lt:     #fef5ec;
  --clr-focus:       #1a6fc4;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;

  --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
  --shadow-md: 0 4px 12px rgba(0,0,0,.10);
  --shadow-lg: 0 8px 32px rgba(0,0,0,.12);

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --transition: 200ms ease;
}

/* ── Base ─────────────────────────────────────────────────────── */
html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--clr-bg);
  color: var(--clr-text);
  line-height: 1.6;
  font-size: 1rem;
  min-width: 320px;
}

img { max-width: 100%; display: block; }
a { color: inherit; }

/* ── Focus visible ────────────────────────────────────────────── */
:focus-visible {
  outline: 3px solid var(--clr-focus);
  outline-offset: 3px;
  border-radius: 2px;
}

/* ── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100px;
  left: 1rem;
  background: var(--clr-focus);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Header ───────────────────────────────────────────────────── */
.site-header {
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
  height: 64px;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  text-decoration: none;
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--clr-text);
}
.logo-mark {
  width: 34px;
  height: 34px;
  background: var(--clr-accent);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
}
.logo-mark svg { fill: #fff; }

/* Search */
.search-form {
  display: flex;
  align-items: center;
  background: var(--clr-surface-2);
  border: 1.5px solid var(--clr-border);
  border-radius: 100px;
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
  max-width: 480px;
}
.search-form:focus-within {
  border-color: var(--clr-focus);
  box-shadow: 0 0 0 3px rgba(26,111,196,.15);
  outline: none;
}
.search-form:focus-within .search-input:focus { outline: none; }

.search-input {
  flex: 1;
  border: none;
  background: transparent;
  padding: .55rem 1rem;
  font-size: .9rem;
  color: var(--clr-text);
  min-width: 0;
}
.search-input::placeholder { color: var(--clr-text-muted); }
.search-input:focus { outline: none; }

.search-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: .55rem .85rem;
  color: var(--clr-text-muted);
  display: grid;
  place-items: center;
  transition: color var(--transition);
}
.search-btn:hover { color: var(--clr-accent); }

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: .25rem;
}

.icon-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: .55rem;
  border-radius: var(--radius-sm);
  color: var(--clr-text);
  display: grid;
  place-items: center;
  position: relative;
  transition: background var(--transition), color var(--transition);
}
.icon-btn:hover { background: var(--clr-surface-2); color: var(--clr-accent); }

.cart-count {
  position: absolute;
  top: 2px;
  right: 2px;
  background: var(--clr-accent);
  color: #fff;
  font-size: .65rem;
  font-weight: 700;
  min-width: 17px;
  height: 17px;
  border-radius: 100px;
  display: grid;
  place-items: center;
  line-height: 1;
}

/* ── Nav ──────────────────────────────────────────────────────── */
.site-nav {
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
}
.nav-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.nav-inner::-webkit-scrollbar { display: none; }

.nav-link {
  text-decoration: none;
  font-size: .88rem;
  font-weight: 500;
  color: var(--clr-text-muted);
  padding: .7rem 1rem;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: color var(--transition), border-color var(--transition);
}
.nav-link:hover, .nav-link[aria-current="page"] {
  color: var(--clr-text);
  border-bottom-color: var(--clr-accent);
}

/* ── Utility ──────────────────────────────────────────────────── */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.section-title {
  font-size: clamp(1.2rem, 3vw, 1.55rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.2;
}

.view-all-link {
  font-size: .85rem;
  font-weight: 600;
  color: var(--clr-accent);
  text-decoration: none;
  white-space: nowrap;
}
.view-all-link:hover { text-decoration: underline; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .4rem;
  padding: .6rem 1.25rem;
  border-radius: 100px;
  font-size: .88rem;
  font-weight: 600;
  cursor: pointer;
  border: 2px solid transparent;
  text-decoration: none;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), box-shadow var(--transition);
  line-height: 1;
}
.btn-primary {
  background: var(--clr-accent);
  color: #fff;
  border-color: var(--clr-accent);
}
.btn-primary:hover {
  background: var(--clr-accent-hover);
  border-color: var(--clr-accent-hover);
}
.btn-outline {
  background: transparent;
  color: var(--clr-text);
  border-color: var(--clr-border);
}
.btn-outline:hover { border-color: var(--clr-text); }

.btn-sm { padding: .45rem .95rem; font-size: .8rem; }

/* ── Hero ─────────────────────────────────────────────────────── */
.hero {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  color: #fff;
  padding: 4rem 0;
  overflow: hidden;
  position: relative;
}

.hero-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.hero-eyebrow {
  display: inline-block;
  background: rgba(192,57,43,.25);
  color: #f1948a;
  font-size: .78rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: .3rem .75rem;
  border-radius: 100px;
  margin-bottom: 1rem;
  border: 1px solid rgba(192,57,43,.4);
}

.hero-title {
  font-size: clamp(2rem, 5vw, 3.25rem);
  font-weight: 900;
  letter-spacing: -.04em;
  line-height: 1.1;
  margin-bottom: 1rem;
}

.hero-title em {
  font-style: normal;
  color: #f1948a;
}

.hero-desc {
  font-size: 1.05rem;
  color: rgba(255,255,255,.75);
  margin-bottom: 2rem;
  max-width: 440px;
  line-height: 1.65;
}

.hero-cta { display: flex; gap: .75rem; flex-wrap: wrap; }

.hero-image-wrap {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 4/3;
  background: rgba(255,255,255,.06);
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-img-placeholder {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* SVG hero illustration */
.hero-illustration {
  width: 100%;
  height: 100%;
}

/* ── Promo bar ────────────────────────────────────────────────── */
.promo-bar {
  background: var(--clr-accent);
  color: #fff;
  text-align: center;
  font-size: .82rem;
  font-weight: 600;
  letter-spacing: .02em;
  padding: .55rem 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
}
.promo-bar a { color: #fff; text-underline-offset: 3px; }

/* ── Section spacing ─────────────────────────────────────────── */
.section { padding: 3.5rem 0; }
.section + .section { border-top: 1px solid var(--clr-border); }

/* ── Product cards ───────────────────────────────────────────── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
  position: relative;
}
.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--clr-surface-2);
  overflow: hidden;
}

.product-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 300ms ease;
}
.product-card:hover .product-img { transform: scale(1.04); }

.product-badge {
  position: absolute;
  top: .6rem;
  left: .6rem;
  font-size: .72rem;
  font-weight: 700;
  padding: .25rem .55rem;
  border-radius: 100px;
  line-height: 1;
}
.badge-new  { background: #1a6fc4; color: #fff; }
.badge-sale { background: var(--clr-accent); color: #fff; }
.badge-hot  { background: var(--clr-deal); color: #fff; }

.product-wishlist {
  position: absolute;
  top: .5rem;
  right: .5rem;
  background: var(--clr-surface);
  border: 1.5px solid var(--clr-border);
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  cursor: pointer;
  color: var(--clr-text-muted);
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] {
  color: var(--clr-accent);
  border-color: var(--clr-accent);
  background: var(--clr-accent-lt);
}
.product-wishlist[aria-pressed="true"] svg { fill: var(--clr-accent); }

.product-body {
  padding: 1rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: .35rem;
}

.product-category {
  font-size: .73rem;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--clr-text-muted);
}

.product-name {
  font-size: .95rem;
  font-weight: 700;
  line-height: 1.35;
  color: var(--clr-text);
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .35rem;
  font-size: .78rem;
  color: var(--clr-text-muted);
}
.stars { color: #f0a500; letter-spacing: .05em; }

.product-price-row {
  display: flex;
  align-items: center;
  gap: .5rem;
  flex-wrap: wrap;
  margin-top: auto;
}

.price-current {
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--clr-text);
}
.price-original {
  font-size: .85rem;
  color: var(--clr-text-muted);
  text-decoration: line-through;
}
.price-save {
  font-size: .72rem;
  font-weight: 700;
  color: var(--clr-accent);
  background: var(--clr-accent-lt);
  padding: .15rem .4rem;
  border-radius: 4px;
}

.product-footer {
  padding: 0 1rem 1rem;
}
.add-to-cart {
  width: 100%;
}

/* ── Deals section ───────────────────────────────────────────── */
.deals-section { background: var(--clr-surface-2); }

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.25rem;
}

.deal-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  display: grid;
  grid-template-columns: 1fr 88px;
  gap: 1rem;
  align-items: center;
  transition: box-shadow var(--transition), transform var(--transition);
}
.deal-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.deal-card-big {
  grid-column: 1 / -1;
  background: linear-gradient(135deg, var(--clr-deal-lt), #fff);
  border-color: #f0c080;
  grid-template-columns: 1fr 140px;
  padding: 2rem;
}

.deal-info { display: flex; flex-direction: column; gap: .5rem; }

.deal-label {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--clr-deal);
}

.deal-name {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--clr-text);
}
.deal-card-big .deal-name { font-size: 1.2rem; }

.deal-price-row { display: flex; align-items: center; gap: .5rem; flex-wrap: wrap; }
.deal-current { font-size: 1.15rem; font-weight: 800; }
.deal-original { font-size: .88rem; color: var(--clr-text-muted); text-decoration: line-through; }
.deal-pct {
  background: var(--clr-deal);
  color: #fff;
  font-size: .72rem;
  font-weight: 800;
  padding: .2rem .45rem;
  border-radius: 4px;
}

.deal-timer {
  display: flex;
  gap: .3rem;
  align-items: center;
  font-size: .78rem;
  color: var(--clr-text-muted);
}
.timer-unit {
  background: var(--clr-surface-2);
  border-radius: 4px;
  padding: .15rem .4rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  min-width: 28px;
  text-align: center;
  font-size: .8rem;
  color: var(--clr-text);
}

.deal-thumb {
  aspect-ratio: 1;
  border-radius: var(--radius-sm);
  background: var(--clr-surface-2);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.deal-thumb svg { opacity: .3; }

/* ── Categories strip ────────────────────────────────────────── */
.categories-strip {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 1rem;
}

.category-chip {
  background: var(--clr-surface);
  border: 1.5px solid var(--clr-border);
  border-radius: var(--radius-md);
  padding: 1.1rem .75rem;
  text-align: center;
  text-decoration: none;
  color: var(--clr-text);
  font-size: .85rem;
  font-weight: 600;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .5rem;
  transition: border-color var(--transition), box-shadow var(--transition), background var(--transition);
}
.category-chip:hover {
  border-color: var(--clr-accent);
  background: var(--clr-accent-lt);
  box-shadow: var(--shadow-sm);
}
.category-icon {
  font-size: 1.6rem;
  line-height: 1;
}

/* ── Editorial / Blog ────────────────────────────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.5rem;
}

.article-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
.article-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.article-card-featured {
  grid-column: 1 / 3;
  flex-direction: row;
}
.article-card-featured .article-image { flex: 1; }
.article-card-featured .article-body  { flex: 1; }

.article-image {
  aspect-ratio: 16/9;
  background: var(--clr-surface-2);
  overflow: hidden;
  flex-shrink: 0;
}
.article-card-featured .article-image { aspect-ratio: auto; min-height: 220px; }

.article-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 300ms ease;
}
.article-card:hover .article-img { transform: scale(1.04); }

.article-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  flex: 1;
}

.article-tag {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--clr-accent);
}

.article-title {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.35;
  color: var(--clr-text);
  text-decoration: none;
}
.article-card-featured .article-title { font-size: 1.2rem; }
.article-title:hover { text-decoration: underline; }

.article-excerpt {
  font-size: .88rem;
  color: var(--clr-text-muted);
  line-height: 1.55;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.article-meta {
  font-size: .78rem;
  color: var(--clr-text-muted);
  margin-top: auto;
  padding-top: .5rem;
  border-top: 1px solid var(--clr-border);
  display: flex;
  gap: .75rem;
  flex-wrap: wrap;
}

/* ── Trust / USP bar ─────────────────────────────────────────── */
.usp-bar {
  background: var(--clr-surface);
  border-top: 1px solid var(--clr-border);
  border-bottom: 1px solid var(--clr-border);
}
.usp-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 1.5rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1.5rem;
}
.usp-item {
  display: flex;
  align-items: center;
  gap: .75rem;
}
.usp-icon {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  background: var(--clr-accent-lt);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  color: var(--clr-accent);
}
.usp-text strong { display: block; font-size: .9rem; font-weight: 700; }
.usp-text span   { font-size: .8rem; color: var(--clr-text-muted); }

/* ── Newsletter ──────────────────────────────────────────────── */
.newsletter-section {
  background: linear-gradient(135deg, #1a1a2e 0%, #0f3460 100%);
  color: #fff;
  padding: 3.5rem 0;
  text-align: center;
}
.newsletter-inner { max-width: 520px; margin: 0 auto; padding: 0 1.5rem; }
.newsletter-section .section-title { color: #fff; margin-bottom: .75rem; }
.newsletter-section p { color: rgba(255,255,255,.75); font-size: .95rem; margin-bottom: 1.5rem; }

.newsletter-form {
  display: flex;
  gap: .5rem;
  flex-wrap: wrap;
  justify-content: center;
}
.newsletter-email {
  flex: 1;
  min-width: 240px;
  padding: .7rem 1.1rem;
  border-radius: 100px;
  border: none;
  font-size: .9rem;
  background: rgba(255,255,255,.12);
  color: #fff;
  border: 1.5px solid rgba(255,255,255,.2);
}
.newsletter-email::placeholder { color: rgba(255,255,255,.55); }
.newsletter-email:focus {
  outline: none;
  border-color: #fff;
  background: rgba(255,255,255,.18);
}
.newsletter-form:focus-within {
  /* parent form shouldn't steal focus outline; handled by input itself */
}
.newsletter-notice {
  font-size: .75rem;
  color: rgba(255,255,255,.5);
  margin-top: .75rem;
}

/* ── Footer ──────────────────────────────────────────────────── */
.site-footer {
  background: #111;
  color: rgba(255,255,255,.7);
  padding: 3rem 0 1.5rem;
}
.footer-grid {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 2.5rem;
  margin-bottom: 2.5rem;
}
.footer-brand .logo { color: #fff; margin-bottom: .75rem; }
.footer-brand p { font-size: .88rem; line-height: 1.65; max-width: 260px; }

.footer-col h3 {
  font-size: .82rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: .85rem;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: .45rem; }
.footer-col a {
  font-size: .88rem;
  text-decoration: none;
  color: rgba(255,255,255,.65);
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }

.footer-bottom {
  max-width: 1280px;
  margin: 0 auto;
  padding: 1.25rem 1.5rem 0;
  border-top: 1px solid rgba(255,255,255,.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  font-size: .8rem;
}
.footer-bottom a { color: rgba(255,255,255,.5); text-decoration: none; }
.footer-bottom a:hover { color: #fff; }

/* ── Cart drawer ─────────────────────────────────────────────── */
.cart-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.45);
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition);
}
.cart-overlay.is-open { opacity: 1; pointer-events: auto; }

.cart-drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 360px;
  max-width: 95vw;
  background: var(--clr-surface);
  box-shadow: var(--shadow-lg);
  z-index: 201;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform 300ms cubic-bezier(.4,0,.2,1);
}
.cart-drawer.is-open { transform: translateX(0); }

.cart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--clr-border);
}
.cart-header h2 { font-size: 1.1rem; font-weight: 700; }

.cart-body {
  flex: 1;
  overflow-y: auto;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.cart-empty {
  text-align: center;
  color: var(--clr-text-muted);
  font-size: .9rem;
  padding: 2rem 0;
}
.cart-item {
  display: grid;
  grid-template-columns: 64px 1fr auto;
  gap: .75rem;
  align-items: start;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--clr-border);
}
.cart-item:last-child { border-bottom: none; }
.cart-item-thumb {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-sm);
  background: var(--clr-surface-2);
  overflow: hidden;
}
.cart-item-name { font-size: .88rem; font-weight: 600; }
.cart-item-price { font-size: .88rem; color: var(--clr-text-muted); }
.cart-item-remove {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--clr-text-muted);
  font-size: 1.1rem;
  padding: 0;
  line-height: 1;
  transition: color var(--transition);
}
.cart-item-remove:hover { color: var(--clr-accent); }

.cart-footer {
  padding: 1.25rem 1.5rem;
  border-top: 1px solid var(--clr-border);
  display: flex;
  flex-direction: column;
  gap: .75rem;
}
.cart-total {
  display: flex;
  justify-content: space-between;
  font-weight: 700;
}
.cart-total-val { font-size: 1.1rem; }

/* ── Toast notification ──────────────────────────────────────── */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 300;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .5rem;
  pointer-events: none;
}
.toast {
  background: #1a1a1a;
  color: #fff;
  padding: .65rem 1.25rem;
  border-radius: 100px;
  font-size: .88rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 250ms ease, transform 250ms ease;
  white-space: nowrap;
  pointer-events: none;
}
.toast.show {
  opacity: 1;
  transform: translateY(0);
}

/* ── Responsive ──────────────────────────────────────────────── */
@media (max-width: 1024px) {
  .editorial-grid {
    grid-template-columns: 1fr 1fr;
  }
  .article-card-featured {
    grid-column: 1 / -1;
    flex-direction: column;
  }
  .article-card-featured .article-image { aspect-ratio: 16/7; min-height: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .header-inner { grid-template-columns: auto auto; gap: .75rem; }
  .search-form { display: none; }
  .hero-inner { grid-template-columns: 1fr; }
  .hero-image-wrap { display: none; }
  .hero { padding: 2.5rem 0; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card-big { grid-template-columns: 1fr 100px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .article-card-featured { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
  .footer-brand { grid-column: 1 / -1; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .hero-title { font-size: 1.75rem; }
  .section { padding: 2.5rem 0; }
}

/* ── Forced colors ───────────────────────────────────────────── */
@media (forced-colors: active) {
  .product-card, .deal-card, .article-card, .category-chip {
    border-color: ButtonBorder;
  }
  .btn-primary {
    background: ButtonFace;
    color: ButtonText;
    border-color: ButtonBorder;
  }
  .cart-count { background: Highlight; color: HighlightText; }
  .product-wishlist { border-color: ButtonBorder; }
}

/* ── Reduced motion ──────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    transition-duration: .01ms !important;
  }
  html { scroll-behavior: auto; }
}
