+/* ── Reset & tokens ───────────────────────────────────────────── */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --clr-bg:          #f8f7f5;
+  --clr-surface:     #ffffff;
+  --clr-surface-2:   #f1efec;
+  --clr-border:      #e2deda;
