+  --clr-focus:       #1a6fc4;
+
+  --radius-sm: 6px;
+  --radius-md: 12px;
+  --radius-lg: 20px;
+
+  --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
+  --shadow-md: 0 4px 12px rgba(0,0,0,.10);
+  --shadow-lg: 0 8px 32px rgba(0,0,0,.12);
+
+  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
+  --transition: 200ms ease;
+}
+
+/* ── Base ─────────────────────────────────────────────────────── */
+html { scroll-behavior: smooth; }
+
+body {
+  font-family: var(--font-sans);
+  background: var(--clr-bg);
+  color: var(--clr-text);
+  line-height: 1.6;
+  font-size: 1rem;
+  min-width: 320px;
+}
+
+img { max-width: 100%; display: block; }
+a { color: inherit; }
+
+/* ── Focus visible ────────────────────────────────────────────── */
+:focus-visible {
+  outline: 3px solid var(--clr-focus);
+  outline-offset: 3px;
+  border-radius: 2px;
+}
+
+/* ── Skip link ────────────────────────────────────────────────── */
+.skip-link {
+  position: absolute;
+  top: -100px;
+  left: 1rem;
+  background: var(--clr-focus);
+  color: #fff;
+  padding: .5rem 1rem;
+  border-radius: var(--radius-sm);
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 9999;
+  transition: top var(--transition);
+}
+.skip-link:focus { top: 1rem; }
+
+/* ── Header ───────────────────────────────────────────────────── */
+.site-header {
+  background: var(--clr-surface);
+  border-bottom: 1px solid var(--clr-border);
+  position: sticky;
+  top: 0;
+  z-index: 100;
+}
+
+.header-inner {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 0 1.5rem;
+  display: grid;
+  grid-template-columns: auto 1fr auto;
+  align-items: center;
+  gap: 1.5rem;
+  height: 64px;
+}
+
+/* Logo */
+.logo {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  text-decoration: none;
+  font-size: 1.35rem;
+  font-weight: 800;
+  letter-spacing: -.03em;
+  color: var(--clr-text);
+}
+.logo-mark {
+  width: 34px;
+  height: 34px;
+  background: var(--clr-accent);
+  border-radius: var(--radius-sm);
+  display: grid;
+  place-items: center;
+}
+.logo-mark svg { fill: #fff; }
+
+/* Search */
+.search-form {
+  display: flex;
+  align-items: center;
+  background: var(--clr-surface-2);
+  border: 1.5px solid var(--clr-border);
+  border-radius: 100px;
+  overflow: hidden;
+  transition: border-color var(--transition), box-shadow var(--transition);
+  max-width: 480px;
+}
+.search-form:focus-within {
+  border-color: var(--clr-focus);
+  box-shadow: 0 0 0 3px rgba(26,111,196,.15);
+  outline: none;
+}
+.search-form:focus-within .search-input:focus { outline: none; }
+
+.search-input {
+  flex: 1;
+  border: none;
+  background: transparent;
+  padding: .55rem 1rem;
+  font-size: .9rem;
+  color: var(--clr-text);
+  min-width: 0;
+}
+.search-input::placeholder { color: var(--clr-text-muted); }
+.search-input:focus { outline: none; }
+
+.search-btn {
+  background: none;
+  border: none;
+  cursor: pointer;
+  padding: .55rem .85rem;
+  color: var(--clr-text-muted);
+  display: grid;
+  place-items: center;
+  transition: color var(--transition);
+}
+.search-btn:hover { color: var(--clr-accent); }
+
+/* Header actions */
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: .25rem;
+}
+
+.icon-btn {
+  background: none;
+  border: none;
+  cursor: pointer;
+  padding: .55rem;
+  border-radius: var(--radius-sm);
+  color: var(--clr-text);
+  display: grid;
+  place-items: center;
+  position: relative;
+  transition: background var(--transition), color var(--transition);
+}
+.icon-btn:hover { background: var(--clr-surface-2); color: var(--clr-accent); }
+
+.cart-count {
+  position: absolute;
+  top: 2px;
+  right: 2px;
+  background: var(--clr-accent);
+  color: #fff;
+  font-size: .65rem;
+  font-weight: 700;
+  min-width: 17px;
+  height: 17px;
+  border-radius: 100px;
+  display: grid;
+  place-items: center;
+  line-height: 1;
+}
+
+/* ── Nav ──────────────────────────────────────────────────────── */
+.site-nav {
+  background: var(--clr-surface);
+  border-bottom: 1px solid var(--clr-border);
+}
+.nav-inner {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 0 1.5rem;
+  display: flex;
+  gap: 0;
+  overflow-x: auto;
+  scrollbar-width: none;
+}
+.nav-inner::-webkit-scrollbar { display: none; }
+
+.nav-link {
+  text-decoration: none;
+  font-size: .88rem;
+  font-weight: 500;
+  color: var(--clr-text-muted);
+  padding: .7rem 1rem;
+  white-space: nowrap;
+  border-bottom: 2px solid transparent;
+  transition: color var(--transition), border-color var(--transition);
+}
+.nav-link:hover, .nav-link[aria-current="page"] {
+  color: var(--clr-text);
+  border-bottom-color: var(--clr-accent);
+}
+
+/* ── Utility ──────────────────────────────────────────────────── */
+.container {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 0 1.5rem;
+}
+
+.section-header {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 1rem;
+  margin-bottom: 1.5rem;
+  flex-wrap: wrap;
+}
+
+.section-title {
+  font-size: clamp(1.2rem, 3vw, 1.55rem);
+  font-weight: 800;
+  letter-spacing: -.03em;
+  line-height: 1.2;
+}
+
+.view-all-link {
+  font-size: .85rem;
+  font-weight: 600;
+  color: var(--clr-accent);
+  text-decoration: none;
+  white-space: nowrap;
+}
+.view-all-link:hover { text-decoration: underline; }
+
+/* Buttons */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: .4rem;
+  padding: .6rem 1.25rem;
+  border-radius: 100px;
+  font-size: .88rem;
+  font-weight: 600;
+  cursor: pointer;
+  border: 2px solid transparent;
+  text-decoration: none;
+  transition: background var(--transition), color var(--transition),
+              border-color var(--transition), box-shadow var(--transition);
+  line-height: 1;
+}
+.btn-primary {
+  background: var(--clr-accent);
+  color: #fff;
+  border-color: var(--clr-accent);
+}
+.btn-primary:hover {
+  background: var(--clr-accent-hover);
+  border-color: var(--clr-accent-hover);
+}
+.btn-outline {
+  background: transparent;
+  color: var(--clr-text);
+  border-color: var(--clr-border);
+}
+.btn-outline:hover { border-color: var(--clr-text); }
+
+.btn-sm { padding: .45rem .95rem; font-size: .8rem; }
+
+/* ── Hero ─────────────────────────────────────────────────────── */
+.hero {
+  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
+  color: #fff;
+  padding: 4rem 0;
+  overflow: hidden;
+  position: relative;
+}
+
+.hero-inner {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 0 1.5rem;
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 3rem;
+  align-items: center;
+}
+
+.hero-eyebrow {
+  display: inline-block;
+  background: rgba(192,57,43,.25);
+  color: #f1948a;
+  font-size: .78rem;
+  font-weight: 700;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  padding: .3rem .75rem;
+  border-radius: 100px;
+  margin-bottom: 1rem;
+  border: 1px solid rgba(192,57,43,.4);
+}
+
+.hero-title {
+  font-size: clamp(2rem, 5vw, 3.25rem);
+  font-weight: 900;
