}

.deal-thumb {
  aspect-ratio: 1;
  border-radius: var(--radius-sm);
  background: var(--clr-surface-2);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.deal-thumb svg { opacity: .3; }

/* ── Categories strip ────────────────────────────────────────── */
.categories-strip {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
