+  { label: "Sale",      icon: "🏷️", href: "#" },
+];
+
+const ARTICLES = [
+  {
+    id: 1,
+    tag: "Style Guide",
+    title: "How to Build a Capsule Wardrobe for Every Season",
+    excerpt:
+      "A capsule wardrobe isn't about having fewer choices — it's about making every piece work harder. Discover the 12 essentials our stylists swear by.",
+    date: "May 2, 2026",
+    readTime: "5 min read",
+    featured: true,
+    color: "#8B9DC3",
+  },
+  {
+    id: 2,
+    tag: "Sustainability",
+    title: "Our Journey to Carbon-Neutral Shipping",
+    excerpt:
+      "We partnered with reforestation projects to offset every parcel we send. Here's what that means for you and the planet.",
+    date: "Apr 28, 2026",
+    readTime: "3 min read",
+    featured: false,
+    color: "#8FA98B",
+  },
+  {
+    id: 3,
+    tag: "Trend Report",
+    title: "The Textures Dominating Autumn 2026",
+    excerpt:
+      "Bouclé, sherpa, and brushed flannel are back in force. See how our designers are styling the season's tactile must-haves.",
+    date: "Apr 20, 2026",
+    readTime: "4 min read",
+    featured: false,
+    color: "#C4A882",
+  },
+];
+
+/* ── Cart state ───────────────────────────────────────────────── */
+let cart = [];
+let dealTimers = {};
+
+/* ── Render helpers ───────────────────────────────────────────── */
+
+function starsHtml(rating) {
+  const full  = Math.floor(rating);
+  const half  = rating % 1 >= 0.5 ? 1 : 0;
+  const empty = 5 - full - half;
+  return "★".repeat(full) + (half ? "½" : "") + "☆".repeat(empty);
+}
+
+function formatPrice(n) {
+  return "$" + n.toFixed(0);
+}
+
+function savePct(current, original) {
+  return Math.round((1 - current / original) * 100);
+}
+
+/* ── Product card ─────────────────────────────────────────────── */
+function renderProduct(p) {
+  const save = p.originalPrice ? savePct(p.price, p.originalPrice) : null;
+  const inWishlist = false;
+
+  const badgeHtml = p.badge
+    ? `<span class="product-badge badge-${p.badge}" aria-label="${p.badgeLabel}">${p.badgeLabel}</span>`
+    : "";
+
+  const priceHtml = p.originalPrice
+    ? `<span class="price-current">${formatPrice(p.price)}</span>
+       <span class="price-original" aria-label="Original price">${formatPrice(p.originalPrice)}</span>
+       <span class="price-save" aria-label="Save ${save}%">-${save}%</span>`
+    : `<span class="price-current">${formatPrice(p.price)}</span>`;
+
+  return `
+    <article class="product-card" aria-label="${p.name}">
+      <div class="product-image-wrap">
+        ${badgeHtml}
+        <button
+          class="product-wishlist"
+          aria-pressed="false"
+          aria-label="Add ${p.name} to wishlist"
+          data-wishlist-id="${p.id}"
+        >
+          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">
+            <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
+          </svg>
+        </button>
+        <svg class="hero-illustration" viewBox="0 0 240 240" role="img" aria-label="Product image for ${p.name}" style="background:${p.color}22; width:100%; height:100%;">
+          <rect width="240" height="240" fill="${p.color}22"/>
+          <rect x="60" y="60" width="120" height="120" rx="16" fill="${p.color}" opacity=".7"/>
+          <text x="120" y="130" text-anchor="middle" font-size="40" fill="white" opacity=".9">${p.category === "Accessories" ? "👜" : p.category === "Footwear" ? "👟" : p.category === "Outerwear" ? "🧥" : p.category === "Knitwear" ? "🧶" : "👕"}</text>
+        </svg>
+      </div>
+      <div class="product-body">
+        <span class="product-category">${p.category}</span>
+        <h3 class="product-name">${p.name}</h3>
+        <div class="product-rating">
+          <span class="stars" aria-hidden="true">${starsHtml(p.rating)}</span>
+          <span>${p.rating} (${p.reviews})</span>
+        </div>
+        <div class="product-price-row">
+          ${priceHtml}
+        </div>
+      </div>
+      <div class="product-footer">
+        <button
+          class="btn btn-primary btn-sm add-to-cart"
+          data-product-id="${p.id}"
+          aria-label="Add ${p.name} to cart"
+        >
+          Add to cart
+        </button>
+      </div>
+    </article>`;
+}
+
+/* ── Deal card ────────────────────────────────────────────────── */
+function renderDeal(d) {
+  const timerHtml = `
+    <div class="deal-timer" aria-label="Offer ends in">
+      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
+      <span class="timer-unit" id="timer-h-${d.id}" aria-label="hours">00</span>h
+      <span class="timer-unit" id="timer-m-${d.id}" aria-label="minutes">00</span>m
+      <span class="timer-unit" id="timer-s-${d.id}" aria-label="seconds">00</span>s
+    </div>`;
+
+  return `
+    <article class="deal-card${d.big ? " deal-card-big" : ""}" aria-label="${d.name} — ${d.pct}% off">
+      <div class="deal-info">
+        <span class="deal-label">${d.label}</span>
+        <h3 class="deal-name">${d.name}</h3>
+        <div class="deal-price-row">
+          <span class="deal-current">${formatPrice(d.currentPrice)}</span>
+          <span class="deal-original" aria-label="Original price">${formatPrice(d.originalPrice)}</span>
+          <span class="deal-pct" aria-label="${d.pct}% off">-${d.pct}%</span>
+        </div>
+        ${timerHtml}
+        <button
+          class="btn btn-primary btn-sm"
+          style="margin-top:.75rem; align-self:flex-start"
+          data-product-id="${d.id}"
+          aria-label="Add ${d.name} to cart"
+        >
+          Grab this deal
+        </button>
+      </div>
+      <div class="deal-thumb" aria-hidden="true">
+        <svg viewBox="0 0 88 88" width="88" height="88" role="presentation">
+          <rect width="88" height="88" fill="${d.color}33" rx="8"/>
+          <rect x="18" y="18" width="52" height="52" rx="8" fill="${d.color}" opacity=".7"/>
+        </svg>
+      </div>
+    </article>`;
+}
+
+/* ── Category chip ───────────────────────────────────────────── */
+function renderCategory(c) {
+  return `
+    <a class="category-chip" href="${c.href}">
+      <span class="category-icon" aria-hidden="true">${c.icon}</span>
+      ${c.label}
+    </a>`;
+}
+
+/* ── Article card ────────────────────────────────────────────── */
+function renderArticle(a) {
+  return `
+    <article class="article-card${a.featured ? " article-card-featured" : ""}">
+      <div class="article-image">
+        <svg class="article-img" viewBox="0 0 480 270" role="img" aria-label="Article image for: ${a.title}" style="background:${a.color}22;">
+          <rect width="480" height="270" fill="${a.color}22"/>
+          <rect x="40" y="40" width="400" height="190" rx="12" fill="${a.color}" opacity=".35"/>
+          <text x="240" y="145" text-anchor="middle" font-size="56" opacity=".5">${a.tag === "Style Guide" ? "👗" : a.tag === "Sustainability" ? "🌿" : "✨"}</text>
+        </svg>
+      </div>
+      <div class="article-body">
+        <span class="article-tag">${a.tag}</span>
+        <a href="#" class="article-title">${a.title}</a>
+        <p class="article-excerpt">${a.excerpt}</p>
+        <div class="article-meta">
+          <span>${a.date}</span>
+          <span>${a.readTime}</span>
+        </div>
+      </div>
+    </article>`;
+}
+
+/* ── Countdown timer ─────────────────────────────────────────── */
+function updateTimers() {
+  DEALS.forEach((d) => {
+    if (!dealTimers[d.id]) dealTimers[d.id] = d.endsIn;
+    if (dealTimers[d.id] > 0) dealTimers[d.id]--;
+
+    const secs = dealTimers[d.id];
+    const h = Math.floor(secs / 3600);
+    const m = Math.floor((secs % 3600) / 60);
+    const s = secs % 60;
+
+    const pad = (n) => String(n).padStart(2, "0");
+
+    const hEl = document.getElementById(`timer-h-${d.id}`);
+    const mEl = document.getElementById(`timer-m-${d.id}`);
+    const sEl = document.getElementById(`timer-s-${d.id}`);
+    if (hEl) hEl.textContent = pad(h);
+    if (mEl) mEl.textContent = pad(m);
+    if (sEl) sEl.textContent = pad(s);
+  });
+}
+
+/* ── Cart ─────────────────────────────────────────────────────── */
+function addToCart(productId) {
+  const product =
+    PRODUCTS.find((p) => p.id === productId) ||
+    DEALS.find((d) => d.id === productId);
+  if (!product) return;
+
+  const name = product.name;
+  const price = product.price || product.currentPrice;
+  const existing = cart.find((i) => i.id === productId && i.name === name);
+
+  if (existing) {
+    existing.qty++;
+  } else {
+    cart.push({ id: productId, name, price, qty: 1, color: product.color });
+  }
+
+  updateCartUI();
+  showToast(`"${name}" added to cart`);
+}
+
+function removeFromCart(index) {
+  const name = cart[index]?.name;
+  cart.splice(index, 1);
+  updateCartUI();
+  if (name) showToast(`"${name}" removed`);
+}
+
+function updateCartUI() {
+  const total = cart.reduce((s, i) => s + i.price * i.qty, 0);
+  const count = cart.reduce((s, i) => s + i.qty, 0);
+
+  // Badge
+  const badge = document.getElementById("cart-count");
+  if (badge) {
+    badge.textContent = count;
+    badge.hidden = count === 0;
+  }
+
+  // Cart body
+  const body = document.getElementById("cart-body");
+  if (!body) return;
+
+  if (cart.length === 0) {
+    body.innerHTML = `<p class="cart-empty">Your cart is empty.</p>`;
+  } else {
+    body.innerHTML = cart
+      .map(
+        (item, i) => `
+      <div class="cart-item">
+        <div class="cart-item-thumb" aria-hidden="true">
+          <svg viewBox="0 0 64 64" width="64" height="64" role="presentation">
+            <rect width="64" height="64" fill="${item.color}33" rx="6"/>
+            <rect x="12" y="12" width="40" height="40" rx="6" fill="${item.color}" opacity=".7"/>
+          </svg>
+        </div>
+        <div>
+          <p class="cart-item-name">${item.name}</p>
+          <p class="cart-item-price">${formatPrice(item.price)} × ${item.qty}</p>
+        </div>
+        <button
+          class="cart-item-remove"
+          aria-label="Remove ${item.name} from cart"
+          data-remove-index="${i}"
+        >×</button>
+      </div>`
+      )
+      .join("");
+  }
+
+  // Total
+  const totalEl = document.getElementById("cart-total-val");
+  if (totalEl) totalEl.textContent = formatPrice(total);
+}
+
+/* ── Toast ────────────────────────────────────────────────────── */
+function showToast(message) {
+  const container = document.getElementById("toast-container");
+  if (!container) return;
+
+  const toast = document.createElement("div");
+  toast.className = "toast";
+  toast.setAttribute("role", "status");
+  toast.setAttribute("aria-live", "polite");
+  toast.textContent = message;
+  container.appendChild(toast);
+
+  // Force reflow then animate in
+  requestAnimationFrame(() => {
+    requestAnimationFrame(() => toast.classList.add("show"));
+  });
+
+  setTimeout(() => {
+    toast.classList.remove("show");
+    toast.addEventListener("transitionend", () => toast.remove(), { once: true });
+  }, 2800);
+}
+
+/* ── Cart drawer open/close ──────────────────────────────────── */
+let lastFocusBeforeCart = null;
+
+function openCart() {
+  lastFocusBeforeCart = document.activeElement;
+  const overlay = document.getElementById("cart-overlay");
+  const drawer  = document.getElementById("cart-drawer");
+  overlay.classList.add("is-open");
+  drawer.classList.add("is-open");
+  overlay.removeAttribute("hidden");
+  drawer.removeAttribute("aria-hidden");
+  document.body.style.overflow = "hidden";
+  document.getElementById("cart-close")?.focus();
+}
+
+function closeCart() {
+  const overlay = document.getElementById("cart-overlay");
+  const drawer  = document.getElementById("cart-drawer");
+  overlay.classList.remove("is-open");
+  drawer.classList.remove("is-open");
+  setTimeout(() => overlay.setAttribute("hidden", ""), 300);
+  drawer.setAttribute("aria-hidden", "true");
+  document.body.style.overflow = "";
+  lastFocusBeforeCart?.focus();
+}
+
+/* ── Newsletter ──────────────────────────────────────────────── */
+function handleNewsletter(e) {
+  e.preventDefault();
+  const input  = e.target.querySelector(".newsletter-email");
+  const notice = document.getElementById("newsletter-notice");
+  if (!input.value.includes("@")) {
+    input.setAttribute("aria-invalid", "true");
+    if (notice) {
+      notice.textContent = "Please enter a valid email address.";
+      notice.style.color = "#f1948a";
+    }
+    input.focus();
+    return;
+  }
+  input.removeAttribute("aria-invalid");
+  input.value = "";
+  if (notice) {
+    notice.textContent = "🎉 You're subscribed! Check your inbox for a welcome gift.";
+    notice.style.color = "rgba(255,255,255,.7)";
+  }
+  showToast("Subscribed successfully!");
+}
+
+/* ── Wishlist toggle ─────────────────────────────────────────── */
+function toggleWishlist(btn, productId) {
+  const pressed = btn.getAttribute("aria-pressed") === "true";
+  btn.setAttribute("aria-pressed", String(!pressed));
+  const product = PRODUCTS.find((p) => p.id === productId);
+  if (product) {
+    showToast(pressed ? `Removed from wishlist` : `"${product.name}" saved to wishlist`);
+  }
+}
+
+/* ── Init ─────────────────────────────────────────────────────── */
+document.addEventListener("DOMContentLoaded", () => {
+  // Render products
+  const productsGrid = document.getElementById("products-grid");
+  if (productsGrid) {
+    productsGrid.innerHTML = PRODUCTS.map(renderProduct).join("");
+  }
+
+  // Render deals
+  const dealsGrid = document.getElementById("deals-grid");
+  if (dealsGrid) {
+    dealsGrid.innerHTML = DEALS.map(renderDeal).join("");
+  }
+
+  // Render categories
+  const categoriesStrip = document.getElementById("categories-strip");
+  if (categoriesStrip) {
+    categoriesStrip.innerHTML = CATEGORIES.map(renderCategory).join("");
+  }
+
+  // Render editorial
+  const editorialGrid = document.getElementById("editorial-grid");
+  if (editorialGrid) {
+    editorialGrid.innerHTML = ARTICLES.map(renderArticle).join("");
+  }
+
+  // Start cart
+  updateCartUI();
+
+  // Start timers
+  updateTimers();
+  setInterval(updateTimers, 1000);
+
+  // ── Event delegation ──
+
+  document.addEventListener("click", (e) => {
+    // Add to cart (product or deal)
+    const addBtn = e.target.closest("[data-product-id]");
+    if (addBtn) {
+      const id = parseInt(addBtn.dataset.productId, 10);
+      addToCart(id);
+      return;
+    }
+
+    // Wishlist
+    const wishlistBtn = e.target.closest("[data-wishlist-id]");
+    if (wishlistBtn) {
+      const id = parseInt(wishlistBtn.dataset.wishlistId, 10);
+      toggleWishlist(wishlistBtn, id);
+      return;
+    }
+
+    // Remove from cart
+    const removeBtn = e.target.closest("[data-remove-index]");
+    if (removeBtn) {
+      removeFromCart(parseInt(removeBtn.dataset.removeIndex, 10));
+      return;
+    }
+
+    // Cart overlay click-outside
+    if (e.target.id === "cart-overlay") {
+      closeCart();
+    }
+  });
+
+  // Open cart
+  document.getElementById("cart-btn")?.addEventListener("click", openCart);
+
+  // Close cart
+  document.getElementById("cart-close")?.addEventListener("click", closeCart);
+
+  // Escape closes cart
+  document.addEventListener("keydown", (e) => {
+    if (e.key === "Escape") closeCart();
+  });
+
+  // Newsletter
+  document.getElementById("newsletter-form")?.addEventListener("submit", handleNewsletter);
+
+  // Mobile search toggle
+  document.getElementById("search-toggle")?.addEventListener("click", () => {
+    const mobileSearch = document.getElementById("mobile-search");
+    if (mobileSearch) {
+      const hidden = mobileSearch.hidden;
+      mobileSearch.hidden = !hidden;
+      if (!mobileSearch.hidden) mobileSearch.querySelector("input")?.focus();
+    }
+  });
+});
+
')

